"use client";

import { useState, useMemo, useRef, useEffect, useId } from "react";
import styles from "./roi-calculator.module.css";

// ─── Types ─────────────────────────────────────────────────────────────────

type BillingPeriod = "monthly" | "quarterly" | "annual";
type PlanKey = "starter" | "growth" | "pro";
type PresetKey = "startup" | "midsize" | "enterprise";

interface CalcState {
  billing: BillingPeriod;
  plan: PlanKey;
  teamSize: number;
  manualHours: number;
  hourlyRate: number;
  toolCost: number;
}

interface CalcResult {
  bmo: number;
  byr: number;
  laborSaved: number;
  savings: number;
  net: number;
  roi: number;
  monthlyBenefit: number;
  hrsSaved: number;
  prodGain: number;
}

// ─── Constants ──────────────────────────────────────────────────────────────

const PLAN_PRICES: Record<PlanKey, Record<BillingPeriod, number>> = {
  starter: { monthly: 999, quarterly: 899, annual: 799 },
  growth: { monthly: 1999, quarterly: 1799, annual: 1599 },
  pro: { monthly: 3499, quarterly: 3149, annual: 2799 },
};

const PLAN_LABELS: Record<PlanKey, string> = {
  starter: "Starter",
  growth: "Growth",
  pro: "Pro",
};

const BILLING_LABELS: Record<BillingPeriod, string> = {
  monthly: "Monthly",
  quarterly: "Quarterly",
  annual: "Annual",
};

const BILLING_BADGES: Partial<Record<BillingPeriod, string>> = {
  quarterly: "Save 10%",
  annual: "Save 20%",
};

const PRESETS: Record<PresetKey, Omit<CalcState, "billing">> = {
  startup: {
    plan: "starter",
    teamSize: 8,
    manualHours: 6,
    hourlyRate: 50,
    toolCost: 8000,
  },
  midsize: {
    plan: "growth",
    teamSize: 30,
    manualHours: 8,
    hourlyRate: 60,
    toolCost: 25000,
  },
  enterprise: {
    plan: "pro",
    teamSize: 100,
    manualHours: 10,
    hourlyRate: 75,
    toolCost: 80000,
  },
};

const PRESET_META: Record<PresetKey, { label: string; emoji: string }> = {
  startup: { label: "Startup", emoji: "🚀" },
  midsize: { label: "Growth Agency", emoji: "📈" },
  enterprise: { label: "Enterprise", emoji: "🏢" },
};

const FIELD_TOOLTIPS = {
  teamSize: "Total number of people on your team who spend time on manual tasks.",
  manualHours:
    "Average hours per person per week spent on tasks Boldteq would handle — reporting, QA, revisions, coordination.",
  hourlyRate:
    "Average fully-loaded cost per hour for those team members (salary + benefits ÷ 2,080).",
  toolCost:
    "Annual spend on tools, contractors, or freelancers that Boldteq would replace.",
};

// ─── Helpers ────────────────────────────────────────────────────────────────

function fmt(n: number): string {
  return "$" + Math.round(n).toLocaleString("en-US");
}

function fmtRoi(n: number): string {
  return Math.round(n).toLocaleString("en-US") + "%";
}

function fmtHrs(n: number): string {
  return Math.round(n).toLocaleString("en-US") + " hrs";
}

function fmtPct(n: number): string {
  return n.toFixed(1) + "%";
}

// ─── Slider fill hook ───────────────────────────────────────────────────────

function useSliderFill(
  value: number,
  min: number,
  max: number
): React.RefCallback<HTMLInputElement> {
  return (el: HTMLInputElement | null) => {
    if (!el) return;
    const pct = ((value - min) / (max - min)) * 100;
    el.style.background = `linear-gradient(to right, #019ae6 0%, #019ae6 ${pct}%, #e2e8f0 ${pct}%, #e2e8f0 100%)`;
  };
}

// ─── Tooltip ────────────────────────────────────────────────────────────────

function Tooltip({ text }: { text: string }) {
  const [visible, setVisible] = useState(false);
  const id = useId();

  return (
    <span className={styles.tooltipWrap}>
      <button
        type="button"
        className={styles.tooltipBtn}
        aria-describedby={visible ? id : undefined}
        onMouseEnter={() => setVisible(true)}
        onMouseLeave={() => setVisible(false)}
        onFocus={() => setVisible(true)}
        onBlur={() => setVisible(false)}
        aria-label="More information"
      >
        ?
      </button>
      {visible && (
        <span role="tooltip" id={id} className={styles.tooltipBubble}>
          {text}
        </span>
      )}
    </span>
  );
}

// ─── Slider field ────────────────────────────────────────────────────────────

interface SliderFieldProps {
  label: string;
  tooltip: string;
  value: number;
  min: number;
  max: number;
  step?: number;
  onChange: (v: number) => void;
  badgeSuffix?: string;
}

function SliderField({
  label,
  tooltip,
  value,
  min,
  max,
  step = 1,
  onChange,
  badgeSuffix = "",
}: SliderFieldProps) {
  const fillRef = useSliderFill(value, min, max);
  const inputId = useId();

  return (
    <div className={styles.field}>
      <div className={styles.fieldHeader}>
        <label htmlFor={inputId} className={styles.fieldLabel}>
          {label}
          <Tooltip text={tooltip} />
        </label>
        <span className={styles.badge}>
          {value}
          {badgeSuffix}
        </span>
      </div>
      <input
        id={inputId}
        ref={fillRef}
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(Number(e.target.value))}
        className={styles.slider}
      />
      <div className={styles.sliderRange}>
        <span>
          {min}
          {badgeSuffix}
        </span>
        <span>
          {max}
          {badgeSuffix}
        </span>
      </div>
    </div>
  );
}

// ─── Dollar input field ──────────────────────────────────────────────────────

interface DollarFieldProps {
  label: string;
  tooltip: string;
  value: number;
  min?: number;
  onChange: (v: number) => void;
}

function DollarField({
  label,
  tooltip,
  value,
  min = 0,
  onChange,
}: DollarFieldProps) {
  const inputId = useId();

  return (
    <div className={styles.field}>
      <label htmlFor={inputId} className={styles.fieldLabel}>
        {label}
        <Tooltip text={tooltip} />
      </label>
      <div className={styles.dollarWrap}>
        <span className={styles.dollarSign}>$</span>
        <input
          id={inputId}
          type="number"
          min={min}
          value={value}
          onChange={(e) => {
            const parsed = parseFloat(e.target.value);
            if (!isNaN(parsed) && parsed >= min) onChange(parsed);
          }}
          className={styles.dollarInput}
        />
      </div>
    </div>
  );
}

// ─── Metric card ─────────────────────────────────────────────────────────────

interface MetricCardProps {
  label: string;
  value: string;
  sub?: string;
}

function MetricCard({ label, value, sub }: MetricCardProps) {
  return (
    <div className={styles.metricCard}>
      <div className={styles.metricLabel}>{label}</div>
      <div className={styles.metricValue}>{value}</div>
      {sub && <div className={styles.metricSub}>{sub}</div>}
    </div>
  );
}

// ─── Main component ──────────────────────────────────────────────────────────

export function RoiCalculator() {
  const [state, setState] = useState<CalcState>({
    billing: "monthly",
    plan: "growth",
    teamSize: 10,
    manualHours: 12,
    hourlyRate: 55,
    toolCost: 800,
  });

  // Slider fill refs tracked via callbacks — keep references stable
  const teamSizeRef = useRef<HTMLInputElement | null>(null);
  const manualHoursRef = useRef<HTMLInputElement | null>(null);

  // Update range fill whenever value changes
  useEffect(() => {
    const el = teamSizeRef.current;
    if (!el) return;
    const pct = ((state.teamSize - 1) / (200 - 1)) * 100;
    el.style.background = `linear-gradient(to right, #019ae6 0%, #019ae6 ${pct}%, #e2e8f0 ${pct}%, #e2e8f0 100%)`;
  }, [state.teamSize]);

  useEffect(() => {
    const el = manualHoursRef.current;
    if (!el) return;
    const pct = ((state.manualHours - 1) / (40 - 1)) * 100;
    el.style.background = `linear-gradient(to right, #019ae6 0%, #019ae6 ${pct}%, #e2e8f0 ${pct}%, #e2e8f0 100%)`;
  }, [state.manualHours]);

  function patch(partial: Partial<CalcState>) {
    setState((prev) => ({ ...prev, ...partial }));
  }

  function applyPreset(key: PresetKey) {
    const p = PRESETS[key];
    setState((prev) => ({ ...prev, ...p }));
  }

  const result = useMemo<CalcResult>(() => {
    const bmo = PLAN_PRICES[state.plan][state.billing];
    const byr = bmo * 12;
    const laborSaved =
      state.manualHours * state.hourlyRate * state.teamSize * 52;
    const savings = laborSaved + state.toolCost;
    const net = savings - byr;
    const roi = byr > 0 ? (net / byr) * 100 : 0;
    const monthlyBenefit = savings / 12 - bmo;
    const hrsSaved = state.manualHours * state.teamSize * 52;
    const totalHrs = 40 * state.teamSize * 52;
    const prodGain = totalHrs > 0 ? (hrsSaved / totalHrs) * 100 : 0;

    return {
      bmo,
      byr,
      laborSaved,
      savings,
      net,
      roi,
      monthlyBenefit,
      hrsSaved,
      prodGain,
    };
  }, [state]);

  const netIsPositive = result.net >= 0;

  const teamSizeInputId = useId();
  const manualHoursInputId = useId();

  return (
    <section className={styles.section}>
      <div className={styles.container}>
        {/* ── Header ── */}
        <div className={styles.header}>
          <div className={styles.eyebrowBadge}>ROI Calculator</div>
          <h2 className={styles.title}>
            See Your Real Savings Before You Commit
          </h2>
          <p className={styles.subtitle}>
            Adjust the inputs to match your team. We&apos;ll show exactly how
            much Boldteq saves you annually compared to hiring.
          </p>
        </div>

        {/* ── Preset buttons ── */}
        <div className={styles.presets}>
          {(Object.keys(PRESETS) as PresetKey[]).map((key) => {
            const meta = PRESET_META[key];
            const active = state.plan === PRESETS[key].plan &&
              state.teamSize === PRESETS[key].teamSize;
            return (
              <button
                key={key}
                type="button"
                className={`${styles.presetBtn} ${active ? styles.presetBtnActive : ""}`}
                onClick={() => applyPreset(key)}
              >
                <span>{meta.emoji}</span>
                <span>{meta.label}</span>
              </button>
            );
          })}
        </div>

        {/* ── Two-column layout ── */}
        <div className={styles.layout}>
          {/* ── LEFT: Inputs ── */}
          <div className={styles.leftPanel}>
            <div className={styles.panelTitle}>Tell us about your team</div>

            {/* Plan Selection */}
            <div className={styles.planBlock}>
              {/* Billing toggle */}
              <div className={styles.billingToggle}>
                {(Object.keys(BILLING_LABELS) as BillingPeriod[]).map((b) => (
                  <button
                    key={b}
                    type="button"
                    className={`${styles.billingBtn} ${state.billing === b ? styles.billingBtnActive : ""}`}
                    onClick={() => patch({ billing: b })}
                  >
                    <span>{BILLING_LABELS[b]}</span>
                    {BILLING_BADGES[b] && (
                      <span className={styles.billingBadge}>
                        {BILLING_BADGES[b]}
                      </span>
                    )}
                  </button>
                ))}
              </div>

              {/* Plan buttons */}
              <div className={styles.planButtons}>
                {(Object.keys(PLAN_LABELS) as PlanKey[]).map((p) => (
                  <button
                    key={p}
                    type="button"
                    className={`${styles.planBtn} ${state.plan === p ? styles.planBtnActive : ""}`}
                    onClick={() => patch({ plan: p })}
                  >
                    <span className={styles.planBtnName}>
                      {PLAN_LABELS[p]}
                    </span>
                    <span className={styles.planBtnPrice}>
                      {fmt(PLAN_PRICES[p][state.billing])}/mo
                    </span>
                  </button>
                ))}
              </div>
            </div>

            {/* Team size slider */}
            <div className={styles.field}>
              <div className={styles.fieldHeader}>
                <label htmlFor={teamSizeInputId} className={styles.fieldLabel}>
                  Team Size
                  <Tooltip text={FIELD_TOOLTIPS.teamSize} />
                </label>
                <span className={styles.badge}>{state.teamSize} people</span>
              </div>
              <input
                id={teamSizeInputId}
                ref={teamSizeRef}
                type="range"
                min={1}
                max={200}
                step={1}
                value={state.teamSize}
                onChange={(e) => patch({ teamSize: Number(e.target.value) })}
                className={styles.slider}
              />
              <div className={styles.sliderRange}>
                <span>1</span>
                <span>200</span>
              </div>
            </div>

            {/* Manual hours slider */}
            <div className={styles.field}>
              <div className={styles.fieldHeader}>
                <label
                  htmlFor={manualHoursInputId}
                  className={styles.fieldLabel}
                >
                  Hours per week (manual tasks)
                  <Tooltip text={FIELD_TOOLTIPS.manualHours} />
                </label>
                <span className={styles.badge}>{state.manualHours} hrs</span>
              </div>
              <input
                id={manualHoursInputId}
                ref={manualHoursRef}
                type="range"
                min={1}
                max={40}
                step={0.5}
                value={state.manualHours}
                onChange={(e) =>
                  patch({ manualHours: Number(e.target.value) })
                }
                className={styles.slider}
              />
              <div className={styles.sliderRange}>
                <span>1 hr</span>
                <span>40 hrs</span>
              </div>
            </div>

            {/* Dollar inputs */}
            <DollarField
              label="Average Hourly Rate"
              tooltip={FIELD_TOOLTIPS.hourlyRate}
              value={state.hourlyRate}
              min={10}
              onChange={(v) => patch({ hourlyRate: v })}
            />
            <DollarField
              label="Annual Tool & Contractor Cost"
              tooltip={FIELD_TOOLTIPS.toolCost}
              value={state.toolCost}
              min={0}
              onChange={(v) => patch({ toolCost: v })}
            />
          </div>

          {/* ── RIGHT: Results ── */}
          <div className={styles.rightPanel}>
            {/* Hero savings card */}
            <div className={styles.heroCard}>
              <div className={styles.heroLabel}>
                Your Estimated Annual Savings
              </div>
              <div
                className={`${styles.heroAmount} ${netIsPositive ? styles.heroAmountPositive : styles.heroAmountNegative}`}
              >
                {fmt(result.savings)}
              </div>
              <div className={styles.heroMeta}>
                <span
                  className={`${styles.roiPill} ${netIsPositive ? styles.roiPillPositive : styles.roiPillNegative}`}
                >
                  {fmtRoi(result.roi)} ROI
                </span>
                <span className={styles.heroSubLabel}>in the first year</span>
              </div>
            </div>

            {/* Metrics grid */}
            <div className={styles.metricsGrid}>
              <MetricCard
                label="Hours Saved"
                value={fmtHrs(result.hrsSaved)}
                sub="annually"
              />
              <MetricCard
                label="Monthly Benefit"
                value={fmt(result.monthlyBenefit)}
                sub="after plan cost"
              />
              <MetricCard
                label="Productivity Boost"
                value={fmtPct(result.prodGain)}
                sub="of total work hours"
              />
              <MetricCard
                label="Total Gain"
                value={fmt(result.net)}
                sub="net over plan cost"
              />
            </div>

            {/* Plan summary */}
            <div className={styles.planSummary}>
              <div className={styles.summaryRow}>
                <span className={styles.summaryLabel}>What You&apos;ll Pay</span>
                <span className={styles.summaryValue}>{fmt(result.byr)}/yr</span>
              </div>
              <div className={styles.summaryDivider} />
              <div className={styles.summaryRow}>
                <span className={styles.summaryLabel}>
                  Money You Keep
                </span>
                <span
                  className={`${styles.summaryValue} ${netIsPositive ? styles.summaryPositive : styles.summaryNegative}`}
                >
                  {fmt(result.net)}
                </span>
              </div>
            </div>

            {/* CTA card */}
            <div className={styles.ctaCard}>
              <div className={styles.ctaHeadline}>
                You could save{" "}
                <span className={styles.ctaHighlight}>
                  {fmt(result.savings)}
                </span>{" "}
                this year
              </div>
              <p className={styles.ctaSubtitle}>
                Stop paying {fmt(result.laborSaved)} in labor on tasks Boldteq
                handles end-to-end. Get started today.
              </p>
              <a
                href="https://calendly.com/boldteq/demo"
                className={styles.ctaButton}
                target="_blank"
                rel="noopener noreferrer"
              >
                Schedule a Free Demo
              </a>
              <div className={styles.trustBadges}>
                <span className={styles.trustBadge}>14-day guarantee</span>
                <span className={styles.trustBadgeDot} />
                <span className={styles.trustBadge}>No lock-in</span>
                <span className={styles.trustBadgeDot} />
                <span className={styles.trustBadge}>Cancel anytime</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

