"use client";

import { useState, useMemo, useRef, useEffect, useId } from "react";
import styles from "./roi-calculator.module.css";

// ─── Types ────────────────────────────────────────────────────────────────────

type BillingPeriod = "monthly" | "quarterly" | "annual";
type PlanKey = "starter" | "growth" | "pro";
type PresetKey = "startup" | "midsize" | "enterprise";

interface CalcState {
  billing: BillingPeriod;
  plan: PlanKey;
  teamSize: number;
  manualHours: number;
  hourlyRate: number;
  toolCost: number;
}

interface CalcResult {
  bmo: number;
  byr: number;
  laborSaved: number;
  savings: number;
  net: number;
  roi: number;
  monthlyBenefit: number;
  hrsSaved: number;
  prodGain: number;
}

// ─── Constants ────────────────────────────────────────────────────────────────

const PLAN_PRICES: Record<PlanKey, Record<BillingPeriod, number>> = {
  starter: { monthly: 999, quarterly: 899, annual: 799 },
  growth: { monthly: 1999, quarterly: 1799, annual: 1599 },
  pro: { monthly: 3499, quarterly: 3149, annual: 2799 },
};

const PLAN_LABELS: Record<PlanKey, string> = {
  starter: "Starter",
  growth: "Growth",
  pro: "Pro",
};

const BILLING_LABELS: Record<BillingPeriod, string> = {
  monthly: "Monthly",
  quarterly: "Quarterly",
  annual: "Annual",
};

const BILLING_BADGES: Partial<Record<BillingPeriod, string>> = {
  quarterly: "Save 10%",
  annual: "Save 20%",
};

const PRESETS: Record<PresetKey, Omit<CalcState, "billing">> = {
  startup: {
    plan: "starter",
    teamSize: 8,
    manualHours: 6,
    hourlyRate: 50,
    toolCost: 8000,
  },
  midsize: {
    plan: "growth",
    teamSize: 30,
    manualHours: 8,
    hourlyRate: 60,
    toolCost: 25000,
  },
  enterprise: {
    plan: "pro",
    teamSize: 100,
    manualHours: 10,
    hourlyRate: 75,
    toolCost: 80000,
  },
};

const PRESET_META: Record<PresetKey, { label: string; emoji: string }> = {
  startup: { label: "Startup", emoji: "🚀" },
  midsize: { label: "Growth Agency", emoji: "📈" },
  enterprise: { label: "Enterprise", emoji: "🏢" },
};

const FIELD_TOOLTIPS = {
  teamSize:
    "Total number of people on your team who spend time on manual tasks.",
  manualHours:
    "Average hours per person per week spent on tasks Boldteq would handle — reporting, QA, revisions, coordination.",
  hourlyRate:
    "Average fully-loaded cost per hour for those team members (salary + benefits ÷ 2,080).",
  toolCost:
    "Annual spend on tools, contractors, or freelancers that Boldteq would replace.",
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

function fmt(n: number): string {
  return "$" + Math.round(n).toLocaleString("en-US");
}

function fmtRoi(n: number): string {
  return Math.round(n).toLocaleString("en-US") + "%";
}

function fmtHrs(n: number): string {
  return Math.round(n).toLocaleString("en-US") + " hrs";
}

function fmtPct(n: number): string {
  return n.toFixed(1) + "%";
}

function sliderBg(value: number, min: number, max: number): string {
  const pct = ((value - min) / (max - min)) * 100;
  return `linear-gradient(to right, #019ae6 0%, #019ae6 ${pct}%, #e2e8f0 ${pct}%, #e2e8f0 100%)`;
}

// ─── Tooltip ─────────────────────────────────────────────────────────────────

function Tooltip({ text }: { text: string }) {
  const [visible, setVisible] = useState(false);
  const id = useId();

  return (
    <span className={styles.tooltipWrap}>
      <button
        type="button"
        className={styles.tooltipBtn}
        aria-describedby={visible ? id : undefined}
        aria-label="More information"
        onMouseEnter={() => setVisible(true)}
        onMouseLeave={() => setVisible(false)}
        onFocus={() => setVisible(true)}
        onBlur={() => setVisible(false)}
      >
        ?
      </button>
      {visible && (
        <span role="tooltip" id={id} className={styles.tooltipBubble}>
          {text}
        </span>
      )}
    </span>
  );
}

// ─── Dollar input field ───────────────────────────────────────────────────────

interface DollarFieldProps {
  label: string;
  tooltip: string;
  value: number;
  min?: number;
  onChange: (v: number) => void;
}

function DollarField({
  label,
  tooltip,
  value,
  min = 0,
  onChange,
}: DollarFieldProps) {
  const inputId = useId();

  return (
    <div className={styles.field}>
      <label htmlFor={inputId} className={styles.fieldLabel}>
        {label}
        <Tooltip text={tooltip} />
      </label>
      <div className={styles.dollarWrap}>
        <span className={styles.dollarSign} aria-hidden="true">
          $
        </span>
        <input
          id={inputId}
          type="number"
          min={min}
          value={value}
          onChange={(e) => {
            const parsed = parseFloat(e.target.value);
            if (!isNaN(parsed) && parsed >= min) onChange(parsed);
          }}
          className={styles.dollarInput}
        />
      </div>
    </div>
  );
}

// ─── Metric card ──────────────────────────────────────────────────────────────

interface MetricCardProps {
  label: string;
  value: string;
  sub?: string;
}

function MetricCard({ label, value, sub }: MetricCardProps) {
  return (
    <div className={styles.metricCard}>
      <div className={styles.metricLabel}>{label}</div>
      <div className={styles.metricValue}>{value}</div>
      {sub && <div className={styles.metricSub}>{sub}</div>}
    </div>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────

export function RoiCalculator() {
  const [state, setState] = useState<CalcState>({
    billing: "monthly",
    plan: "growth",
    teamSize: 10,
    manualHours: 12,
    hourlyRate: 55,
    toolCost: 800,
  });

  const teamSizeRef = useRef<HTMLInputElement | null>(null);
  const manualHoursRef = useRef<HTMLInputElement | null>(null);

  // Keep range slider fill track in sync
  useEffect(() => {
    const el = teamSizeRef.current;
    if (!el) return;
    el.style.background = sliderBg(state.teamSize, 1, 200);
  }, [state.teamSize]);

  useEffect(() => {
    const el = manualHoursRef.current;
    if (!el) return;
    el.style.background = sliderBg(state.manualHours, 1, 40);
  }, [state.manualHours]);

  function patch(partial: Partial<CalcState>) {
    setState((prev) => ({ ...prev, ...partial }));
  }

  function applyPreset(key: PresetKey) {
    setState((prev) => ({ ...prev, ...PRESETS[key] }));
  }

  const result = useMemo<CalcResult>(() => {
    const bmo = PLAN_PRICES[state.plan][state.billing];
    const byr = bmo * 12;
    const laborSaved =
      state.manualHours * state.hourlyRate * state.teamSize * 52;
    const savings = laborSaved + state.toolCost;
    const net = savings - byr;
    const roi = byr > 0 ? (net / byr) * 100 : 0;
    const monthlyBenefit = savings / 12 - bmo;
    const hrsSaved = state.manualHours * state.teamSize * 52;
    const totalHrs = 40 * state.teamSize * 52;
    const prodGain = totalHrs > 0 ? (hrsSaved / totalHrs) * 100 : 0;

    return {
      bmo,
      byr,
      laborSaved,
      savings,
      net,
      roi,
      monthlyBenefit,
      hrsSaved,
      prodGain,
    };
  }, [state]);

  const netIsPositive = result.net >= 0;

  const teamSizeId = useId();
  const manualHoursId = useId();

  return (
    <section className={styles.section}>
      <div className={styles.container}>
        {/* Header */}
        <div className={styles.header}>
          <div className={styles.eyebrowBadge}>ROI Calculator</div>
          <h2 className={styles.title}>
            See Your Real Savings Before You Commit
          </h2>
          <p className={styles.subtitle}>
            Adjust the inputs to match your team. We&apos;ll show exactly how
            much Boldteq saves you annually compared to hiring.
          </p>
        </div>

        {/* Preset buttons */}
        <div className={styles.presets}>
          {(Object.keys(PRESETS) as PresetKey[]).map((key) => {
            const { label, emoji } = PRESET_META[key];
            const preset = PRESETS[key];
            const isActive =
              state.plan === preset.plan &&
              state.teamSize === preset.teamSize &&
              state.manualHours === preset.manualHours;

            return (
              <button
                key={key}
                type="button"
                className={`${styles.presetBtn} ${isActive ? styles.presetBtnActive : ""}`}
                onClick={() => applyPreset(key)}
              >
                <span aria-hidden="true">{emoji}</span>
                <span>{label}</span>
              </button>
            );
          })}
        </div>

        {/* Two-column layout */}
        <div className={styles.layout}>
          {/* LEFT: Inputs */}
          <div className={styles.leftPanel}>
            <div className={styles.panelTitle}>Tell us about your team</div>

            {/* Plan Selection block */}
            <div className={styles.planBlock}>
              {/* Billing toggle */}
              <div className={styles.billingToggle}>
                {(Object.keys(BILLING_LABELS) as BillingPeriod[]).map((b) => (
                  <button
                    key={b}
                    type="button"
                    className={`${styles.billingBtn} ${state.billing === b ? styles.billingBtnActive : ""}`}
                    onClick={() => patch({ billing: b })}
                  >
                    <span>{BILLING_LABELS[b]}</span>
                    {BILLING_BADGES[b] && (
                      <span className={styles.billingBadge}>
                        {BILLING_BADGES[b]}
                      </span>
                    )}
                  </button>
                ))}
              </div>

              {/* Plan buttons */}
              <div className={styles.planButtons}>
                {(Object.keys(PLAN_LABELS) as PlanKey[]).map((p) => (
                  <button
                    key={p}
                    type="button"
                    className={`${styles.planBtn} ${state.plan === p ? styles.planBtnActive : ""}`}
                    onClick={() => patch({ plan: p })}
                  >
                    <span className={styles.planBtnName}>
                      {PLAN_LABELS[p]}
                    </span>
                    <span className={styles.planBtnPrice}>
                      {fmt(PLAN_PRICES[p][state.billing])}/mo
                    </span>
                  </button>
                ))}
              </div>
            </div>

            {/* Team size slider */}
            <div className={styles.field}>
              <div className={styles.fieldHeader}>
                <label htmlFor={teamSizeId} className={styles.fieldLabel}>
                  Team Size
                  <Tooltip text={FIELD_TOOLTIPS.teamSize} />
                </label>
                <span className={styles.badge}>{state.teamSize} people</span>
              </div>
              <input
                id={teamSizeId}
                ref={teamSizeRef}
                type="range"
                min={1}
                max={200}
                step={1}
                value={state.teamSize}
                onChange={(e) => patch({ teamSize: Number(e.target.value) })}
                className={styles.slider}
              />
              <div className={styles.sliderRange}>
                <span>1</span>
                <span>200</span>
              </div>
            </div>

            {/* Hours per week slider */}
            <div className={styles.field}>
              <div className={styles.fieldHeader}>
                <label htmlFor={manualHoursId} className={styles.fieldLabel}>
                  Hours / week on manual tasks
                  <Tooltip text={FIELD_TOOLTIPS.manualHours} />
                </label>
                <span className={styles.badge}>{state.manualHours} hrs</span>
              </div>
              <input
                id={manualHoursId}
                ref={manualHoursRef}
                type="range"
                min={1}
                max={40}
                step={0.5}
                value={state.manualHours}
                onChange={(e) =>
                  patch({ manualHours: Number(e.target.value) })
                }
                className={styles.slider}
              />
              <div className={styles.sliderRange}>
                <span>1 hr</span>
                <span>40 hrs</span>
              </div>
            </div>

            {/* Hourly rate dollar input */}
            <DollarField
              label="Average Hourly Rate"
              tooltip={FIELD_TOOLTIPS.hourlyRate}
              value={state.hourlyRate}
              min={10}
              onChange={(v) => patch({ hourlyRate: v })}
            />

            {/* Tool cost dollar input */}
            <DollarField
              label="Annual Tool & Contractor Cost"
              tooltip={FIELD_TOOLTIPS.toolCost}
              value={state.toolCost}
              min={0}
              onChange={(v) => patch({ toolCost: v })}
            />
          </div>

          {/* RIGHT: Results */}
          <div className={styles.rightPanel}>
            {/* Hero savings card */}
            <div className={styles.heroCard}>
              <div className={styles.heroLabel}>
                Your Estimated Annual Savings
              </div>
              <div
                className={`${styles.heroAmount} ${netIsPositive ? styles.heroAmountPositive : styles.heroAmountNegative}`}
              >
                {fmt(result.savings)}
              </div>
              <div className={styles.heroMeta}>
                <span
                  className={`${styles.roiPill} ${netIsPositive ? styles.roiPillPositive : styles.roiPillNegative}`}
                >
                  {fmtRoi(result.roi)} ROI
                </span>
                <span className={styles.heroSubLabel}>in the first year</span>
              </div>
            </div>

            {/* Metrics grid */}
            <div className={styles.metricsGrid}>
              <MetricCard
                label="Hours Saved"
                value={fmtHrs(result.hrsSaved)}
                sub="annually"
              />
              <MetricCard
                label="Monthly Benefit"
                value={fmt(result.monthlyBenefit)}
                sub="after plan cost"
              />
              <MetricCard
                label="Productivity Boost"
                value={fmtPct(result.prodGain)}
                sub="of total work hrs"
              />
              <MetricCard
                label="Total Gain"
                value={fmt(result.net)}
                sub="net over plan cost"
              />
            </div>

            {/* Plan summary */}
            <div className={styles.planSummary}>
              <div className={styles.summaryRow}>
                <span className={styles.summaryLabel}>What You&apos;ll Pay</span>
                <span className={styles.summaryValue}>
                  {fmt(result.byr)}/yr
                </span>
              </div>
              <div className={styles.summaryDivider} />
              <div className={styles.summaryRow}>
                <span className={styles.summaryLabel}>Money You Keep</span>
                <span
                  className={`${styles.summaryValue} ${netIsPositive ? styles.summaryPositive : styles.summaryNegative}`}
                >
                  {fmt(result.net)}
                </span>
              </div>
            </div>

            {/* CTA card */}
            <div className={styles.ctaCard}>
              <div className={styles.ctaHeadline}>
                You could save{" "}
                <span className={styles.ctaHighlight}>
                  {fmt(result.savings)}
                </span>{" "}
                this year
              </div>
              <p className={styles.ctaSubtitle}>
                Stop paying {fmt(result.laborSaved)} in labor on tasks Boldteq
                handles end-to-end.
              </p>
              <a
                href="https://calendly.com/boldteq/demo"
                className={styles.ctaButton}
                target="_blank"
                rel="noopener noreferrer"
              >
                Schedule a Free Demo
              </a>
              <div className={styles.trustBadges}>
                <span className={styles.trustBadge}>14-day guarantee</span>
                <span className={styles.trustBadgeDot} aria-hidden="true" />
                <span className={styles.trustBadge}>No lock-in</span>
                <span className={styles.trustBadgeDot} aria-hidden="true" />
                <span className={styles.trustBadge}>Cancel anytime</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

/* ─── Section wrapper ─────────────────────────────────────────────────────── */

.section {
  background-color: #f5f7fa;
  padding: 80px 5%;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}

/* ─── Header ─────────────────────────────────────────────────────────────── */

.header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  margin-bottom: 32px;
}

.eyebrowBadge {
  display: inline-flex;
  align-items: center;
  height: 32px;
  padding: 0 14px;
  background-color: rgba(33, 207, 255, 0.08);
  border: 1px solid #05bafe;
  border-radius: 20px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 12px;
  font-weight: 700;
  color: #009ce0;
  letter-spacing: 0.04em;
  text-transform: capitalize;
}

.title {
  color: #082753;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 36px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0;
  max-width: 580px;
}

.subtitle {
  color: rgba(8, 39, 83, 0.55);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 16px;
  line-height: 26px;
  max-width: 520px;
  margin: 0;
}

/* ─── Preset buttons ─────────────────────────────────────────────────────── */

.presets {
  display: flex;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 32px;
}

.presetBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background-color: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 100px;
  padding: 8px 18px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  color: #082753;
  cursor: pointer;
  transition: border-color 0.15s ease, background-color 0.15s ease, color 0.15s ease;
}

.presetBtn:hover {
  border-color: #009ce0;
  color: #009ce0;
}

.presetBtnActive {
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  border-color: transparent;
  color: #fff;
}

.presetBtnActive:hover {
  color: #fff;
  filter: brightness(1.06);
}

/* ─── Two-column layout ──────────────────────────────────────────────────── */

.layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  align-items: start;
}

/* ─── Left panel ─────────────────────────────────────────────────────────── */

.leftPanel {
  background-color: #fff;
  border: 1px solid #e8eaed;
  border-radius: 20px;
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  box-shadow: 0 4px 24px rgba(8, 39, 83, 0.06);
}

.panelTitle {
  color: #082753;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

/* ─── Plan selection block ───────────────────────────────────────────────── */

.planBlock {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Billing toggle */
.billingToggle {
  display: flex;
  background-color: #f4f7fa;
  border-radius: 10px;
  padding: 5px 6px;
  gap: 4px;
}

.billingBtn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background-color: transparent;
  border: none;
  border-radius: 8px;
  padding: 7px 8px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 13px;
  font-weight: 500;
  color: #5b616e;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
  white-space: nowrap;
}

.billingBtnActive {
  background-color: #fff;
  color: #082753;
  box-shadow: 0 0 0 1px rgba(8, 39, 83, 0.08), 0 2px 8px rgba(8, 39, 83, 0.08);
}

.billingBadge {
  background-color: rgba(24, 201, 88, 0.1);
  border-radius: 5px;
  color: #18c958;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 11px;
  font-weight: 600;
  padding: 1px 6px;
  line-height: 18px;
}

/* Plan buttons */
.planButtons {
  display: flex;
  gap: 8px;
}

.planBtn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  background-color: #f5f7fa;
  border: 1px solid #e8eaed;
  border-radius: 10px;
  padding: 10px 14px;
  cursor: pointer;
  transition: border-color 0.15s ease, background-color 0.15s ease;
  min-width: 0;
}

.planBtn:hover {
  border-color: #009ce0;
}

.planBtnActive {
  background-color: #082753;
  border-color: #082753;
}

.planBtnActive:hover {
  filter: brightness(1.1);
}

.planBtnName {
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #082753;
  transition: color 0.15s ease;
}

.planBtnActive .planBtnName {
  color: #fff;
}

.planBtnPrice {
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 11px;
  color: rgba(8, 39, 83, 0.5);
  transition: color 0.15s ease;
}

.planBtnActive .planBtnPrice {
  color: rgba(255, 255, 255, 0.7);
}

/* ─── Form fields ────────────────────────────────────────────────────────── */

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.fieldHeader {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}

.fieldLabel {
  display: flex;
  align-items: center;
  gap: 5px;
  color: #082753;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 13px;
  font-weight: 600;
  cursor: default;
}

.badge {
  background-color: #082753;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  border-radius: 6px;
  color: #fff;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 12px;
  font-weight: 700;
  padding: 2px 9px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* ─── Range slider ───────────────────────────────────────────────────────── */

.slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 3px;
  outline: none;
  cursor: pointer;
  /* background is controlled via JS ref */
  background: linear-gradient(to right, #019ae6 0%, #019ae6 50%, #e2e8f0 50%, #e2e8f0 100%);
}

.slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid #019ae6;
  box-shadow: 0 1px 4px rgba(1, 154, 230, 0.3);
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.slider::-webkit-slider-thumb:hover {
  border-color: #21cfff;
  box-shadow: 0 0 0 4px rgba(33, 207, 255, 0.15);
}

.slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid #019ae6;
  box-shadow: 0 1px 4px rgba(1, 154, 230, 0.3);
  cursor: pointer;
}

.sliderRange {
  display: flex;
  justify-content: space-between;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 11px;
  color: rgba(8, 39, 83, 0.4);
  margin-top: -4px;
}

/* ─── Dollar input ───────────────────────────────────────────────────────── */

.dollarWrap {
  position: relative;
  display: flex;
  align-items: center;
}

.dollarSign {
  position: absolute;
  left: 12px;
  color: rgba(8, 39, 83, 0.45);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  pointer-events: none;
  user-select: none;
}

.dollarInput {
  width: 100%;
  padding: 10px 14px 10px 26px;
  background-color: #f5f7fa;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  color: #082753;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  /* hide number spinner */
  -moz-appearance: textfield;
}

.dollarInput::-webkit-outer-spin-button,
.dollarInput::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.dollarInput:focus {
  border-color: #019ae6;
  box-shadow: 0 0 0 3px rgba(1, 154, 230, 0.12);
  background-color: #fff;
}

/* ─── Tooltip ────────────────────────────────────────────────────────────── */

.tooltipWrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.tooltipBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: rgba(8, 39, 83, 0.12);
  border: none;
  color: rgba(8, 39, 83, 0.5);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 10px;
  font-weight: 700;
  cursor: help;
  transition: background-color 0.15s ease;
  flex-shrink: 0;
  padding: 0;
  line-height: 1;
}

.tooltipBtn:hover {
  background-color: rgba(1, 154, 230, 0.2);
  color: #019ae6;
}

.tooltipBubble {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background-color: #082753;
  color: #fff;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 12px;
  line-height: 18px;
  padding: 8px 12px;
  border-radius: 8px;
  width: 220px;
  z-index: 20;
  pointer-events: none;
  box-shadow: 0 4px 16px rgba(8, 39, 83, 0.2);
}

.tooltipBubble::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 5px solid transparent;
  border-top-color: #082753;
}

/* ─── Right panel ────────────────────────────────────────────────────────── */

.rightPanel {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ─── Hero savings card ──────────────────────────────────────────────────── */

.heroCard {
  background-image: linear-gradient(135deg, #019ae6, #082753);
  border-radius: 20px;
  padding: 32px 28px 28px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
}

.heroLabel {
  color: rgba(255, 255, 255, 0.75);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.heroAmount {
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: clamp(38px, 5vw, 54px);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
}

.heroAmountPositive {
  color: #fff;
}

.heroAmountNegative {
  color: #fca5a5;
}

.heroMeta {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: center;
}

.roiPill {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  border-radius: 100px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 13px;
  font-weight: 700;
}

.roiPillPositive {
  background-color: rgba(24, 201, 88, 0.2);
  color: #6ee7a0;
}

.roiPillNegative {
  background-color: rgba(220, 38, 38, 0.25);
  color: #fca5a5;
}

.heroSubLabel {
  color: rgba(255, 255, 255, 0.6);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 13px;
}

/* ─── Metrics grid ───────────────────────────────────────────────────────── */

.metricsGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.metricCard {
  background-color: #fff;
  border: 1px solid #e8eaed;
  border-radius: 14px;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  box-shadow: 0 2px 8px rgba(8, 39, 83, 0.04);
}

.metricLabel {
  color: rgba(8, 39, 83, 0.5);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.metricValue {
  color: #082753;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.metricSub {
  color: rgba(8, 39, 83, 0.4);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 11px;
  line-height: 16px;
}

/* ─── Plan summary ───────────────────────────────────────────────────────── */

.planSummary {
  background-color: #fff;
  border: 1px solid #e8eaed;
  border-radius: 16px;
  padding: 20px 22px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: 0 2px 8px rgba(8, 39, 83, 0.04);
}

.summaryRow {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.summaryLabel {
  color: rgba(8, 39, 83, 0.65);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
}

.summaryValue {
  color: #082753;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 15px;
  font-weight: 700;
  white-space: nowrap;
}

.summaryPositive {
  color: #059669;
}

.summaryNegative {
  color: #dc2626;
}

.summaryDivider {
  border: none;
  border-top: 1px solid #f0f2f5;
}

/* ─── CTA card ───────────────────────────────────────────────────────────── */

.ctaCard {
  background-color: #082753;
  border-radius: 20px;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 14px;
}

.ctaHeadline {
  color: #fff;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.35;
}

.ctaHighlight {
  color: #21cfff;
}

.ctaSubtitle {
  color: rgba(255, 255, 255, 0.6);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 13px;
  line-height: 20px;
  margin: 0;
}

.ctaButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  color: #fff;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 15px;
  font-weight: 700;
  line-height: 1;
  text-decoration: none;
  border-radius: 10px;
  padding: 14px 28px;
  width: 100%;
  transition: filter 0.15s ease;
  cursor: pointer;
}

.ctaButton:hover {
  filter: brightness(1.08);
}

.trustBadges {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}

.trustBadge {
  color: rgba(255, 255, 255, 0.5);
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 12px;
}

.trustBadgeDot {
  display: block;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.25);
  flex-shrink: 0;
}

/* ─── Responsive ─────────────────────────────────────────────────────────── */

@media screen and (max-width: 900px) {
  .layout {
    grid-template-columns: 1fr;
  }

  .rightPanel {
    /* show results below inputs on narrow screens */
    order: -1;
  }
}

@media screen and (max-width: 767px) {
  .section {
    padding: 64px 5%;
  }

  .title {
    font-size: 28px;
  }

  .leftPanel {
    padding: 24px 20px;
    gap: 20px;
  }

  .billingBtn {
    font-size: 12px;
    padding: 6px 6px;
    gap: 4px;
  }

  .billingBadge {
    font-size: 10px;
  }

  .planButtons {
    flex-direction: column;
  }

  .planBtn {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }

  .metricsGrid {
    grid-template-columns: 1fr 1fr;
  }

  .heroCard {
    padding: 24px 20px;
  }
}

@media screen and (max-width: 479px) {
  .metricsGrid {
    grid-template-columns: 1fr;
  }

  .presets {
    flex-direction: column;
    align-items: stretch;
  }

  .presetBtn {
    justify-content: center;
  }

  .billingToggle {
    flex-wrap: wrap;
  }
}
